-- PREPARED ONLY: Y-01..Y-12 separate append-only review for one immutable technical-workspace head.
-- Dependency: ambulatory_technical_evidence_workspace.sql with internal-profile/session binding.
-- Not applied. It changes no native/Android writer, technical evidence event, care record, visit, measure or employee record.
-- Runtime proof still requires PostgreSQL/PostgREST/RLS/grants, two sessions, CAS/deadlock/rollback,
-- SDK argument names, old-writer compatibility, browser/layout and qualified care/privacy/legal acceptance.
begin;
create schema if not exists technical_evidence_review_private;
revoke all on schema technical_evidence_review_private from public,anon,authenticated;
create table if not exists technical_evidence_review_private.review_scopes(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,employee_id uuid not null,qualification_id uuid not null,kind text not null check(kind='technical_operations_review'),qualification_fingerprint text not null check(qualification_fingerprint~'^sha256:[0-9a-f]{64}$'),document_fingerprint text not null check(document_fingerprint~'^sha256:[0-9a-f]{64}$'),approved_at timestamptz not null,valid_until timestamptz not null,revoked_at timestamptz,unique(tenant_id,employee_id,qualification_id,kind,approved_at));
create table if not exists public.technical_evidence_review_roots(id uuid primary key,tenant_id uuid not null,technical_head_id uuid not null,technical_kind text not null,technical_fingerprint text not null check(technical_fingerprint~'^sha256:[0-9a-f]{64}$'),created_at timestamptz not null,unique(tenant_id,technical_head_id,technical_fingerprint));
create table if not exists public.technical_evidence_review_events(id uuid primary key,tenant_id uuid not null,root_id uuid not null references public.technical_evidence_review_roots(id),revision integer not null check(revision between 1 and 2),previous_id uuid,request_id uuid not null unique,action text not null check(action in('request','return','accept')),actor_id uuid not null,actor_name text not null,recorded_at timestamptz not null,reason text not null,required_change text not null,rationale text not null,technical_head_id uuid not null,technical_kind text not null,technical_fingerprint text not null,qualification_original jsonb,fingerprint text not null,packet jsonb not null,unique(root_id,revision));
create table if not exists public.technical_evidence_review_receipts(request_id uuid primary key,tenant_id uuid not null,actor_id uuid not null,root_id uuid not null,event_id uuid not null,packet jsonb not null,original jsonb not null,recorded_at timestamptz not null);
alter table technical_evidence_review_private.review_scopes enable row level security;alter table public.technical_evidence_review_roots enable row level security;alter table public.technical_evidence_review_events enable row level security;alter table public.technical_evidence_review_receipts enable row level security;
revoke all on technical_evidence_review_private.review_scopes,public.technical_evidence_review_roots,public.technical_evidence_review_events,public.technical_evidence_review_receipts from public,anon,authenticated;
create or replace function technical_evidence_review_private.review_immutable()returns trigger language plpgsql security definer set search_path='' as $$begin raise exception 'Technik- und Betriebsfachprüfung bleibt unveränderlich.' using errcode='P0S01';end$$;
drop trigger if exists technical_review_roots_immutable on public.technical_evidence_review_roots;create trigger technical_review_roots_immutable before update or delete on public.technical_evidence_review_roots for each row execute function technical_evidence_review_private.review_immutable();
drop trigger if exists technical_review_events_immutable on public.technical_evidence_review_events;create trigger technical_review_events_immutable before update or delete on public.technical_evidence_review_events for each row execute function technical_evidence_review_private.review_immutable();
drop trigger if exists technical_review_receipts_immutable on public.technical_evidence_review_receipts;create trigger technical_review_receipts_immutable before update or delete on public.technical_evidence_review_receipts for each row execute function technical_evidence_review_private.review_immutable();

create or replace function technical_evidence_review_private.review_source(t uuid,a uuid)returns jsonb language sql security definer set search_path='' as $$select technical_evidence_private.read_context(t,a)-'actorId'-'loadedAt'$$;
create or replace function technical_evidence_review_private.review_original(root uuid)returns jsonb language sql security definer set search_path='' as $$
select jsonb_build_object('id',last_e.id::text,'tenantId',r.tenant_id::text,'rootId',r.id::text,'headId',last_e.id::text,'revision',last_e.revision,'technicalHeadId',r.technical_head_id::text,'technicalKind',r.technical_kind,'technicalFingerprint',r.technical_fingerprint,'reviewedSource',(select first_e.packet->'technicalOriginal' from public.technical_evidence_review_events first_e where first_e.root_id=r.id order by first_e.revision limit 1),'status',case last_e.action when'request'then'requested'when'return'then'returned'else'accepted'end,'history',coalesce((select jsonb_agg(jsonb_build_object('id',e.id::text,'revision',e.revision,'previousId',e.previous_id::text,'requestId',e.request_id::text,'action',e.action,'recordedAt',to_char(e.recorded_at at time zone'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'actorId',e.actor_id::text,'actorName',e.actor_name,'reason',e.reason,'requiredChange',e.required_change,'rationale',e.rationale,'technicalHeadId',e.technical_head_id::text,'technicalKind',e.technical_kind,'technicalFingerprint',e.technical_fingerprint,'qualification',e.qualification_original,'fingerprint',e.fingerprint)order by e.revision)from public.technical_evidence_review_events e where e.root_id=r.id),'[]'::jsonb))
from public.technical_evidence_review_roots r join lateral(select e.* from public.technical_evidence_review_events e where e.root_id=r.id order by e.revision desc limit 1)last_e on true where r.id=root$$;

create or replace function technical_evidence_review_private.read_review_page(t uuid,actor uuid,cursor_at timestamptz,cursor_id uuid,page_size integer)returns jsonb language plpgsql security definer set search_path='' as $$
declare all_rows jsonb;rows jsonb;tail jsonb;next_at text;next_id text;snapshot text;
begin
 perform technical_evidence_private.actor(t,actor,null);
 if page_size is null or page_size<1 or page_size>100 or (cursor_at is null)<>(cursor_id is null) then raise exception 'Seitengröße oder Fortsetzung ist ungültig.' using errcode='22023';end if;
 lock table public.technical_evidence_review_roots,public.technical_evidence_review_events in share mode;
 select coalesce(jsonb_agg(technical_evidence_review_private.review_original(r.id)order by e.recorded_at desc,r.id desc),'[]'::jsonb) into all_rows from public.technical_evidence_review_roots r join lateral(select x.recorded_at from public.technical_evidence_review_events x where x.root_id=r.id order by x.revision desc limit 1)e on true where r.tenant_id=t;
 if jsonb_array_length(all_rows)>10000 or octet_length(all_rows::text)>20000000 then raise exception 'Vollständiger Fachprüfbestand überschreitet die sichere Lesegrenze.' using errcode='22023';end if;
 snapshot:='sha256:'||encode(extensions.digest(convert_to(all_rows::text,'UTF8'),'sha256'),'hex');
 select coalesce(jsonb_agg(v order by ordinal),'[]'::jsonb)into rows from (select v,ordinal from jsonb_array_elements(all_rows)with ordinality as a(v,ordinal)where cursor_at is null or ((v#>>array['history',(jsonb_array_length(v->'history')-1)::text,'recordedAt'])::timestamptz,(v->>'rootId')::uuid)<(cursor_at,cursor_id)order by ordinal limit page_size)page;
 if jsonb_array_length(rows)>0 then tail:=rows->-1;next_at:=tail#>>array['history',(jsonb_array_length(tail->'history')-1)::text,'recordedAt'];next_id:=tail->>'rootId';end if;
 return jsonb_build_object('rows',rows,'nextCursorRecordedAt',next_at,'nextCursorId',next_id,'snapshotFingerprint',snapshot,'totalCount',jsonb_array_length(all_rows));
end$$;

create or replace function technical_evidence_review_private.commit_review(p jsonb)returns jsonb language plpgsql security definer set search_path='' as $$
declare t uuid:=(p->>'tenantId')::uuid;actor uuid:=(p->>'actorId')::uuid;req uuid:=(p->>'requestId')::uuid;action_value text:=p->>'action';expected integer:=(p->>'expectedRevision')::integer;event_ref uuid:=gen_random_uuid();review_root uuid;now_at timestamptz:=clock_timestamp();today date:=(clock_timestamp()at time zone'Europe/Berlin')::date;name text;source jsonb;source_head uuid;source_kind text;source_fingerprint text;prior public.technical_evidence_review_events%rowtype;qualification jsonb;original jsonb;receipt public.technical_evidence_review_receipts%rowtype;fingerprint text;
begin
 if jsonb_typeof(p) is distinct from 'object' or not(p ?& array['schemaVersion','action','requestId','tenantId','actorId','expectedHeadId','expectedRevision','technicalOriginal','reviewOriginal','reason','requiredChange','rationale']) or p-array['schemaVersion','action','requestId','tenantId','actorId','expectedHeadId','expectedRevision','technicalOriginal','reviewOriginal','reason','requiredChange','rationale']<>'{}'::jsonb or octet_length(p::text)>20000000 or length(p->>'reason')>2000 or length(p->>'requiredChange')>4000 or length(p->>'rationale')>4000 or p->>'schemaVersion' is distinct from '1'or action_value not in('request','return','accept')or action_value is null or expected is null or req is null or t is null or actor is null or expected not between 0 and 1 or jsonb_typeof(p->'technicalOriginal')<>'object'or jsonb_typeof(p->'reason') is distinct from 'string'or jsonb_typeof(p->'requiredChange') is distinct from 'string'or jsonb_typeof(p->'rationale') is distinct from 'string' then raise exception 'Technik- und Betriebsfachprüfanfrage ist unvollständig.' using errcode='22023';end if;
 perform technical_evidence_private.actor(t,actor,'correction');
 perform pg_advisory_xact_lock(hashtextextended('technical-workspace-review:'||t::text,0));select*into receipt from public.technical_evidence_review_receipts r where r.request_id=req for update;if found then if receipt.tenant_id<>t or receipt.actor_id<>actor or receipt.packet<>p then raise exception 'Anfragekennung ist anders gebunden.' using errcode='P0S01';end if;return jsonb_build_object('requestId',req::text,'packet',p,'original',receipt.original);end if;
 lock table public.backup_status_records,public.employee_documents,public.employee_employment_details,public.employee_qualifications,public.employees,public.incident_tickets,public.maintenance_windows,public.operations_audit_events,public.profiles,public.release_notes,public.release_packages,public.restore_test_records,public.role_permission_sets,public.role_permissions,public.roles,public.system_error_logs,public.system_health_checks,technical_evidence_private.events,technical_evidence_private.roots,technical_evidence_review_private.review_scopes in share mode;
 source:=technical_evidence_review_private.review_source(t,actor);if source is distinct from p->'technicalOriginal' then raise exception 'Vollständiger aktueller Technik- und Betriebsbestand wurde verändert.' using errcode='P0S01';end if;source_head:=(source#>>'{history,headId}')::uuid;source_kind:=source#>>array['history','events',(jsonb_array_length(source#>'{history,events}')-1)::text,'command','kind'];if source_head is null or btrim(coalesce(source_kind,''))='' then raise exception 'Ein gespeicherter Technik- und Betriebsbestand fehlt.' using errcode='23514';end if;source_fingerprint:='sha256:'||encode(extensions.digest(convert_to(source::text,'UTF8'),'sha256'),'hex');
 if action_value<>'request' and (public.has_permission('release.view') is not true or public.has_permission('security.view') is not true or public.has_permission('release.manage') is not true or public.has_permission('security.manage') is not true or public.has_permission('pflege.documentation.sign') is not true) then raise exception 'Aktuelle Fachprüfrechte fehlen.' using errcode='42501';end if;
 select coalesce(pr.display_name,pr.email)into name from public.profiles pr where pr.id=actor and pr.tenant_id=t and pr.is_active=true;if btrim(coalesce(name,''))=''then raise exception 'Aktiver Akteur fehlt.' using errcode='42501';end if;
 if action_value='request'then if expected<>0 or p->'expectedHeadId' is distinct from 'null'::jsonb or p->'reviewOriginal' is distinct from 'null'::jsonb or length(btrim(p->>'reason'))<10 or p->>'requiredChange'<>''or p->>'rationale'<>''then raise exception 'Prüfanfrage darf keine Entscheidung enthalten.' using errcode='23514';end if;review_root:=event_ref;insert into public.technical_evidence_review_roots(id,tenant_id,technical_head_id,technical_kind,technical_fingerprint,created_at)values(review_root,t,source_head,source_kind,source_fingerprint,now_at);
 else review_root:=(p#>>'{reviewOriginal,rootId}')::uuid;perform 1 from public.technical_evidence_review_roots r where r.id=review_root and r.tenant_id=t and r.technical_head_id=source_head and r.technical_kind=source_kind and r.technical_fingerprint=source_fingerprint for update;if not found then raise exception 'Passende unveränderte Technik- und Betriebsprüfanfrage fehlt.' using errcode='P0S01';end if;select*into prior from public.technical_evidence_review_events e where e.root_id=review_root order by e.revision desc limit 1 for update;if not found or expected<>1 or prior.action<>'request'or prior.id::text<>p->>'expectedHeadId'or technical_evidence_review_private.review_original(review_root)is distinct from p->'reviewOriginal'then raise exception 'Technik- und Betriebsprüfanfrage hat sich geändert.' using errcode='P0S01';end if;if actor=prior.actor_id or exists(select 1 from jsonb_array_elements(source#>'{history,events}')e where e->>'actorId'=actor::text)then raise exception 'Anfragende oder am Technik- und Betriebsbestand beteiligte Person darf nicht selbst entscheiden.' using errcode='42501';end if;
  lock table public.employees,public.employee_employment_details,public.employee_qualifications,public.employee_documents,technical_evidence_review_private.review_scopes in share mode;
  select jsonb_build_object('id',q.id::text,'employeeId',e.id::text,'profileId',e.profile_id::text,'qualificationType',q.qualification_type,'title',q.title,'status',q.status,'issuedAt',to_char(q.issued_at,'YYYY-MM-DD'),'validUntil',to_char(q.valid_until,'YYYY-MM-DD'),'verifiedAt',to_char(q.verified_at at time zone'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'updatedAt',to_char(q.updated_at at time zone'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'documentId',d.id::text,'documentFingerprint',scope.document_fingerprint,'qualificationFingerprint',scope.qualification_fingerprint,'employeeFingerprint','sha256:'||encode(extensions.digest(convert_to(jsonb_build_object('employee',to_jsonb(e),'employment',to_jsonb(ed))::text,'UTF8'),'sha256'),'hex'),'scopeId',scope.id::text,'scopeKind','technical_operations_review','scopeFingerprint','sha256:'||encode(extensions.digest(convert_to(to_jsonb(scope)::text,'UTF8'),'sha256'),'hex'))into qualification from public.employees e join public.employee_employment_details ed on ed.employee_id=e.id and ed.tenant_id=e.tenant_id join public.employee_qualifications q on q.employee_id=e.id and q.tenant_id=e.tenant_id join public.employee_documents d on d.id=q.document_id and d.employee_id=e.id and d.tenant_id=e.tenant_id join technical_evidence_review_private.review_scopes scope on scope.employee_id=e.id and scope.qualification_id=q.id and scope.tenant_id=e.tenant_id and scope.kind='technical_operations_review'where e.tenant_id=t and e.profile_id=actor and e.status='aktiv'and ed.employment_status='active'and coalesce(e.entry_date,e.start_date)<=today and(e.exit_date is null or e.exit_date>=today)and q.status in('valid','expires_soon')and q.verified_at<=now_at and q.updated_at<=now_at and(q.issued_at is null or q.issued_at<=today)and(q.valid_until is null or q.valid_until>=today)and(d.valid_until is null or d.valid_until>=today)and btrim(coalesce(d.storage_path,''))<>''and scope.approved_at<=now_at and scope.valid_until>now_at and scope.revoked_at is null and scope.qualification_fingerprint='sha256:'||encode(extensions.digest(convert_to(to_jsonb(q)::text,'UTF8'),'sha256'),'hex')and scope.document_fingerprint='sha256:'||encode(extensions.digest(convert_to(to_jsonb(d)::text,'UTF8'),'sha256'),'hex')order by scope.approved_at desc,scope.id desc limit 1;
  if qualification is null then raise exception 'Aktuelle Beschäftigung, Qualifikation, Dokument und Technik- und Betriebsprüfbereich fehlen.' using errcode='42501';end if;if action_value='return'then if length(btrim(p->>'reason'))<10 or length(btrim(p->>'requiredChange'))<10 or p->>'rationale'<>''then raise exception 'Rückgabe benötigt Grund und konkrete Änderung.' using errcode='23514';end if;elsif p->>'reason'<>''or p->>'requiredChange'<>''or length(btrim(p->>'rationale'))<10 then raise exception 'Fachliche Annahme benötigt eine konkrete Begründung.' using errcode='23514';end if;
 end if;
 fingerprint:='sha256:'||encode(extensions.digest(convert_to(jsonb_build_object('packet',p,'qualification',qualification)::text,'UTF8'),'sha256'),'hex');insert into public.technical_evidence_review_events(id,tenant_id,root_id,revision,previous_id,request_id,action,actor_id,actor_name,recorded_at,reason,required_change,rationale,technical_head_id,technical_kind,technical_fingerprint,qualification_original,fingerprint,packet)values(event_ref,t,review_root,expected+1,case when expected=0 then null else prior.id end,req,action_value,actor,name,now_at,p->>'reason',p->>'requiredChange',p->>'rationale',source_head,source_kind,source_fingerprint,qualification,fingerprint,p);original:=technical_evidence_review_private.review_original(review_root);insert into public.technical_evidence_review_receipts(request_id,tenant_id,actor_id,root_id,event_id,packet,original,recorded_at)values(req,t,actor,review_root,event_ref,p,original,now_at);return jsonb_build_object('requestId',req::text,'packet',p,'original',original);
end$$;
create or replace function technical_evidence_review_private.confirm_review(t uuid,actor uuid,req uuid,p jsonb)returns jsonb language plpgsql security definer set search_path='' as $$declare r public.technical_evidence_review_receipts;begin perform technical_evidence_private.actor(t,actor,null);select*into r from public.technical_evidence_review_receipts x where x.request_id=req and x.tenant_id=t and x.actor_id=actor;if not found or r.packet is distinct from p then raise exception 'Keine passende unveränderliche Technik- und Betriebsfachprüfquittung.' using errcode='P0S03';end if;return jsonb_build_object('requestId',req::text,'packet',r.packet,'original',r.original);end$$;
create or replace function public.web_read_technical_evidence_review_page(p_tenant_id uuid,p_actor_profile_id uuid,p_cursor_recorded_at timestamptz,p_cursor_id uuid,p_page_size integer)returns jsonb language sql security invoker set search_path='' as $$select technical_evidence_review_private.read_review_page(p_tenant_id,p_actor_profile_id,p_cursor_recorded_at,p_cursor_id,p_page_size)$$;
create or replace function public.web_commit_technical_evidence_review(p_packet jsonb)returns jsonb language sql security invoker set search_path='' as $$select technical_evidence_review_private.commit_review(p_packet)$$;
create or replace function public.web_confirm_technical_evidence_review(p_tenant_id uuid,p_actor_profile_id uuid,p_request_id uuid,p_packet jsonb)returns jsonb language sql security invoker set search_path='' as $$select technical_evidence_review_private.confirm_review(p_tenant_id,p_actor_profile_id,p_request_id,p_packet)$$;
revoke all on function technical_evidence_review_private.review_immutable(),technical_evidence_review_private.review_source(uuid,uuid),technical_evidence_review_private.review_original(uuid),technical_evidence_review_private.read_review_page(uuid,uuid,timestamptz,uuid,integer),technical_evidence_review_private.commit_review(jsonb),technical_evidence_review_private.confirm_review(uuid,uuid,uuid,jsonb)from public,anon,authenticated;
revoke all on function public.web_read_technical_evidence_review_page(uuid,uuid,timestamptz,uuid,integer),public.web_commit_technical_evidence_review(jsonb),public.web_confirm_technical_evidence_review(uuid,uuid,uuid,jsonb)from public,anon;
grant usage on schema technical_evidence_review_private to authenticated;
grant execute on function technical_evidence_review_private.read_review_page(uuid,uuid,timestamptz,uuid,integer),technical_evidence_review_private.commit_review(jsonb),technical_evidence_review_private.confirm_review(uuid,uuid,uuid,jsonb),public.web_read_technical_evidence_review_page(uuid,uuid,timestamptz,uuid,integer),public.web_commit_technical_evidence_review(jsonb),public.web_confirm_technical_evidence_review(uuid,uuid,uuid,jsonb)to authenticated;
commit;
